create database toko_1_4;
use toko_1_4;

CREATE TABLE `karyawan` (
`password` varchar(200) Default NULL COMMENT 'Password login user terenkripsi',
`kode` varchar(40) NOT NULL  Default '' COMMENT 'Kode unik ID karyawan',
`nama` varchar(40) Default NULL COMMENT 'Nama lengkap karyawan',
`level` varchar(10) Default NULL COMMENT 'Level hak akses user',
`login_terakhir` varchar(50) Default NULL COMMENT 'Waktu terakhir login user',
`copy_data` varchar(10) Default NULL COMMENT 'Akses salin data transaksi',
`point` decimal(10,2) Default '0.00' COMMENT 'Akumulasi poin karyawan',
`phk` varchar(5) Default NULL COMMENT 'Status non-aktif (PHK/Resign)',
`alamat` varchar(100) Default NULL COMMENT 'Alamat domisili karyawan',
`jenis` varchar(50) Default 'NONE' COMMENT 'Jenis karyawan (Honorer/Tetap)',
`divisi` varchar(25) Default NULL COMMENT 'Bagian divisi kerja',
`persen_shu` decimal(15,2) Default '0.00' COMMENT 'Persentase Bagi Hasil Usaha',
`jammasuk` time Default NULL COMMENT 'Jadwal jam masuk kerja',
`jamkeluar` time Default NULL COMMENT 'Jadwal jam keluar kerja',
`status` varchar(15) Default NULL COMMENT 'Status keaktifan karyawan',
`tanggal` date Default NULL COMMENT 'Tanggal pendaftaran/aktif',
`kasawal` decimal(15,2) Default '0.00' COMMENT 'Saldo kas awal saat buka kasir',
`login_x` int(11) Default NULL COMMENT 'Counter jumlah login',
`keterangan` varchar(50) Default NULL COMMENT 'Catatan tambahan karyawan');
ALTER TABLE karyawan ADD PRIMARY KEY (`kode`);

