CREATE TABLE `kas` (
`kode` varchar(25) NOT NULL  Default '' COMMENT 'Kode unik akun kas/bank',
`nama` varchar(50) Default NULL COMMENT 'Nama akun kas',
`saldo` decimal(10,2) Default '0.00' COMMENT 'Saldo saat ini',
`default_toko` varchar(5) Default 'False' COMMENT 'Setting sebagai default kas toko',
`default_return_pembelian` varchar(5) Default 'False' COMMENT 'Setting sebagai default kas retur pembelian',
`default_pembelian` varchar(5) Default 'False' COMMENT 'Setting sebagai default kas pembelian',
`default_pembelian_read_only` varchar(5) Default 'False' COMMENT 'Akses read-only kas pembelian',
`default_produksi` varchar(5) Default 'False' COMMENT 'Setting sebagai default kas produksi',
`default_pengiriman_po` varchar(5) Default 'False' COMMENT 'Setting sebagai default kas pengiriman PO',
`default_pengiriman_po_read_only` varchar(5) Default 'False' COMMENT 'Akses read-only kas pengiriman PO');
ALTER TABLE kas ADD PRIMARY KEY (`kode`);

INSERT INTO kas VALUES ("KP","KAS PERUSAHAAN","1000000","True","True","True","False","False","False","False"); 

CREATE TABLE `kas_awal` (
`kode_kas` varchar(50) NOT NULL  Default '' COMMENT 'Kode referensi akun kas',
`saldo` decimal(15,2) Default '0.00' COMMENT 'Saldo awal kas',
`tanggal` date Default NULL COMMENT 'Tanggal mutasi saldo awal');
ALTER TABLE kas_awal ADD PRIMARY KEY (`kode_kas`);

